 .SRMODE("SYNC")) u_geometry_index_rom(
 .doa(geometry_index_read),.dia(16'd0),.addra({1'b0,address[15:6]}),.bytea(1'b0),.bytewea(1'b0),
 .csa(1'b1),.wea(1'b0),.clka(clk),.rsta(1'b0),.ocea(1'b1),
 .dob(),.dib(16'd0),.addrb(11'd0),.byteb(1'b0),.byteweb(1'b0),
 .csb(1'b0),.web(1'b0),.clkb(clk),.rstb(1'b0),.oceb(1'b1));
 wire [8:0] geometry_index0=geometry_index_read[8:0];
reg [5:0] geometry_offset0;reg [17:0] dx20;reg [15:0] dy20;
 reg [4:0] travel0;reg [7:0] seed0;reg [3:0] localx0,localy0;
 reg [8:0] phase0,x0;reg [7:0] y0;
 reg [7:0] fine_seed0;reg [2:0] finex0,finey0;
 reg fine1;
 reg [1:0] shape1;reg [18:0] radius1;
 reg [4:0] travel1,dot1;reg [7:0] seed1;
 reg [4:0] floor1;reg [2:0] grain1;
 reg [15:0] colour2,colour3,colour4;
 reg [3:0] bx,by,level,bloom;reg gold;
 always @(posedge clk)begin
  geometry_offset0<=address[5:0];dx20<=dx*dx;dy20<=dy*dy;
  travel0<=phase[8]?dx-phase[7:0]+y[4:0]:dx+phase[7:0]+y[4:0];
  seed0<=seed;localx0<=moving_x[3:0];localy0<=moving_y[3:0];
  fine_seed0<=fine_seed;finex0<=moving_x[2:0];finey0<=moving_y[2:0];
  phase0<=phase;x0<=x;y0<=y;
  shape1<=geometry_dictionary[{geometry_index0,geometry_offset0}];radius1<=dx20+({3'd0,dy20}<<2);
  travel1<=travel0;seed1<=seed0;
  fine1<=fine_seed0[7:5]==3 && finex0==fine_seed0[2:0] && finey0==fine_seed0[5:3];
  bx=localx0>seed0[3:0]?localx0-seed0[3:0]:seed0[3:0]-localx0;
  by=localy0>seed0[7:4]?localy0-seed0[7:4]:seed0[7:4]-localy0;
  dot1<={1'b0,bx}+{1'b0,by};floor1<=x0[6:2]+phase0[6:2]+y0[6:2];
  grain1<=x0[2:0]^y0[2:0];
  level=0;gold=0;
  case(shape1)
   1:begin level=2;if(travel1<3)level=6;end
   2:begin level=3;if(travel1<10)level=5;if(travel1<4)level=8;if(travel1<2)level=11;if(grain1==0 && travel1<10)level=13;end
   3:begin level=3;if(floor1<4)level=9;else if(floor1<9)level=5;end
   default:level=0;
  endcase
  bloom=0;
  if(radius1<16)bloom=15;
  else if(radius1<36)bloom=13;
  else if(radius1<64)bloom=11;
  else if(radius1<100)bloom=9;
  else if(radius1<169)bloom=7;
  else if(radius1<256)bloom=5;
  else if(radius1<400)bloom=3;
  else if(radius1<625)bloom=2;
  else if(radius1<900)bloom=1;
  if(bloom>level)level=bloom;
  if(fine1 && level<6)level=6;
  if(seed1[7:6]!=0)begin
   if(dot1==0)begin level=seed1[0]?15:12;gold=seed1[4:0]==3;end
   else if(seed1[2:1]==0)begin
    if(dot1==1 && level<10)level=10;
    else if(dot1==2 && level<6)level=6;
    else if(dot1==3 && level<3)level=3;
   end else if(dot1==1 && level<4)level=4;
  end
  colour2<=gold?16'hfeaa:blue(level);colour3<=colour2;colour4<=colour3;
 end
 assign rgb=colour4;
